const token = pm.environment.get("access_token");

if (!token) {
    throw new Error("access_token is missing. Run Login user first.");
}

pm.request.headers.upsert({
    key: "Authorization",
    value: `Bearer ${token}`
});

const jsonData = pm.response.json();

pm.test("Status code is 401", function () {
    pm.response.to.have.status(401);
});

pm.test("Missing token error message is returned", function () {
    pm.expect(jsonData.message).to.eql("Access Token is required");
});

pm.test("User data is not returned", function () {
    pm.expect(jsonData).to.not.have.property("username");
});

